const items = $input.all();
const results = [];

for (const item of items) {
  const { method = "GET", url, headers = {}, body, maxRetries = 3 } = item.json;
  let attempt = 0;
  let lastError = null;
  let response = null;

  while (attempt < maxRetries) {
    attempt += 1;
    try {
      response = await this.helpers.httpRequest({
        method,
        url,
        headers,
        body,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
      });

      const status = response.statusCode;
      if (status && status < 500 && status !== 429) {
        break; // success, or a non-retryable client error
      }

      const retryAfterHeader = response.headers && response.headers["retry-after"];
      const waitMs = retryAfterHeader ? Number(retryAfterHeader) * 1000 : Math.min(2 ** attempt * 500, 8000);
      await new Promise((resolve) => setTimeout(resolve, waitMs));
    } catch (err) {
      lastError = err;
      const waitMs = Math.min(2 ** attempt * 500, 8000);
      await new Promise((resolve) => setTimeout(resolve, waitMs));
    }
  }

  results.push({
    json: {
      ok: !!response && response.statusCode < 400,
      statusCode: response ? response.statusCode : null,
      body: response ? response.body : null,
      attempts: attempt,
      error: lastError
        ? lastError.message
        : response && response.statusCode >= 400
        ? `HTTP ${response.statusCode}`
        : null,
    },
  });
}

return results;
